var DATA = {"gate": "Story acceptance", "criteria": "Code reviewed|Tests passing|Acceptance criteria verified|Docs updated", "evidence": "PR with 2 approvals and green CI"};
console.log("Readiness gate: " + DATA.gate);
var criteria = DATA.criteria.split("|").map(function (s) { return s.trim(); });
var met = 0;
criteria.forEach(function (c, i) {
  // deterministic check: criterion counts as met unless it names a known gap
  var ok = !/missing|pending|todo|tbd/i.test(c);
  if (ok) met++;
  console.log("  [" + (ok ? "MET " : "GAP ") + "] " + c);
});
var pct = Math.round((met / criteria.length) * 100);
console.log("Evidence: " + DATA.evidence);
console.log("RESULT: " + met + "/" + criteria.length + " criteria met (" + pct + "%) — " + (pct === 100 ? "READY" : "NOT READY") + ".");

